sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var fetchSysID = function(tableName, id) {
        var gr = new GlideRecord(tableName);
        gr.addQuery('number', id);
        gr.query();

        if (gr.next()) {
            return gr.getValue('sys_id');
        } else {
            gs.info('No matching records found.');
            return;
        }
    };

    var fetchDocumentContent = function(tableName, sysID) {
        var attachment = new GlideSysAttachment();
        var agr = attachment.getAttachments(tableName, sysID);
        var attachmentContent = "";
		//Assuming there will be only one file attached.
        if (agr.next()) {
            gs.info("File name: " + agr.getValue("file_name"));
            attachmentContent = attachment.getContent(agr);
            return attachmentContent;
        }
        return attachmentContent;
    };

    //fetch IDs to get Content of Attached Documents of job description and applicant resume
    var jobID = fetchSysID("x_1761730_ats_job_listings", current.getDisplayValue("job_id"));
    var applicantID = fetchSysID("x_1761730_ats_applicants", current.getDisplayValue("applicant_id"));
    gs.info("Job Listing ID:" + jobID);
    gs.info("Applicant ID:" + applicantID);

    //fetch contents of the attached Documents
    var jobDescription = fetchDocumentContent("x_1761730_ats_job_listings", jobID);
    var resume = fetchDocumentContent("x_1761730_ats_applicants", applicantID);
    if (jobDescription !== "" && resume !== "") {
        try {
            var messages = [{
                    "role": "system",
                    "content": "You are a hiring expert. Given the job description and a resume, evaluate how well the candidate matches the job. Provide 1. A score from 1 (poor match) to 10 (perfect match)2. A brief explanation of your reasoning in 2 lines. Provide the above information in key value dict with score and explanation as keys"
                },
                {
                    "role": "user",
                    "content": "Following are the job description and resume Job Description is Job Title: Job Description: " + jobDescription + "Candidate Resume: " + resume
                }
            ];
            var payload = {
                'model': "sonar-pro",
                'messages': messages,
                'temperature': 0.7
            };
        } catch (ex) {
            var payloadErrorMessage = ex.message;
            gs.error("Problem while building the payload:" + payloadErrorMessage);
			gs.error("payload:" + payload);
        }

		//Invoke the rest API to rank the resume
        try {
            var r = new sn_ws.RESTMessageV2('x_1761730_ats.Resume Ranking', 'Get Resume Ranking');
            try {
                r.setRequestBody(JSON.stringify(payload));
            } catch (ex) {
                gs.error("Problem with preparing request body:" + ex.message);
				gs.error("payload:" + payload);
            }
            var response = r.executeAsync();
            var responseBody = response.getBody();
            var httpStatus = response.getStatusCode();
            if (httpStatus === 200) {
                var jsonResponseBody = JSON.parse(responseBody);
                if (jsonResponseBody["choices"] && jsonResponseBody["choices"].length > 0) {
                    gs.info("response from API content");
                    gs.info(jsonResponseBody["choices"][0]['message']['content']);
                    try {
                        var responseContent = JSON.parse(jsonResponseBody["choices"][0]['message']['content']);
                    } catch (ex) {
                        gs.info("Problem with parsing the content:" + ex.message);
                    }

					//update the response in respective fields
                    current.resume_ranking = responseContent["score"] || 0;
                    current.resume_ranking_summary = responseContent["explanation"] || "";
                    current.update();
                }
            }
        } catch (ex) {
            var message = ex.message;
            gs.error("Problem with resume ranking:" + message);
        }
    } else {
        gs.info("No content in job Description document or Resume");
    }
})(current, previous);
